    attempt_id          TEXT PRIMARY KEY REFERENCES attempts(attempt_id) ON DELETE RESTRICT,
    boot_id             TEXT NOT NULL,
    root_pid            INTEGER NOT NULL CHECK (root_pid > 0),
    root_started_at     INTEGER NOT NULL CHECK (root_started_at > 0),
