CREATE TABLE macro_task_deletions (
    deletion_id      TEXT PRIMARY KEY,
    target_kind      TEXT NOT NULL CHECK (target_kind IN ('macro-task','micro-task-tree')),
    target_id        TEXT NOT NULL,
    UNIQUE(target_kind, target_id)
);
